<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {Button,Input,NativeSelect,StatusNotice,useHostContext} from '@openclaw-plugins/control-ui-kit';
import {useManagementRequest} from './management-request';
import type {KnowledgeHistory,KnowledgeHistoryRecord,KnowledgeIndex,KnowledgeDiff,KnowledgeChange} from './knowledge-model';
const props=defineProps<{agentId:string;projectId:string;activeSnapshot?:string;activeCommit?:string;renderedSnapshot?:string}>(),emit=defineEmits<{snapshot:[index:KnowledgeIndex];prefetch:[index:KnowledgeIndex];latest:[];open:[snapshotId:string,path:string];compare:[before:string|undefined,after:string,path:string,previousPath?:string]}>();
const context=useHostContext(),request=useManagementRequest(context,()=>props.agentId),safe=(v:unknown)=>context.value.host.redact(String(v??''));
const records=ref<KnowledgeHistoryRecord[]>([]),head=ref(''),cursor=ref<string|null>(null),position=ref(-1),playing=ref(false),busy=ref(false),error=ref(''),notice=ref(''),speed=ref('1000'),diff=ref<KnowledgeDiff>(),filter=ref(''),kind=ref(''),date=ref('');
let alive=true,epoch=0,timer:ReturnType<typeof setTimeout>|undefined,scrubTimer:ReturnType<typeof setTimeout>|undefined;const prepared=new Map<string,KnowledgeIndex>(),diffs=new Map<string,KnowledgeDiff>();
const chronological=computed(()=>[...records.value].reverse()),changes=computed(()=>diff.value?.changes.filter(c=>(!kind.value||c.kind===kind.value)&&`${c.path} ${c.entry.title} ${c.entry.featureId??''} ${c.entry.area??''}`.toLowerCase().includes(filter.value.toLowerCase()))??[]);
async function load(){const valid=request.capture();try{const h=await request.invoke<KnowledgeHistory>('knowledgeChanges',{projectId:props.projectId,...(head.value?{head:head.value}:{}),...(cursor.value?{cursor:cursor.value}:{})});if(!alive||!valid())return;const current=chronological.value[position.value]?.id;head.value=h.head;records.value.push(...h.records);cursor.value=h.nextCursor;if(current)position.value=chronological.value.findIndex(r=>r.id===current);if(!h.complete)notice.value=h.source==='observations'?'此项目没有可用 Git 历史，仅展示首次索引后的观察记录。':'历史不完整：仅展示本地可读取的主线提交。';}catch{if(alive)error.value='历史读取失败，请重试。';}}
async function prepare(record:KnowledgeHistoryRecord,token:number){if(prepared.has(record.id))return prepared.get(record.id)!;const valid=request.capture();let first=true;while(alive&&token===epoch&&valid()){const index=await request.invoke<KnowledgeIndex>('knowledgeSnapshot',{projectId:props.projectId,head:head.value,revision:record.id,...(first?{retry:true}:{})});first=false;if(!alive||token!==epoch||!valid())throw Error('stale');if(index.state==='error')throw Error('failed');if(index.state==='ready'&&index.snapshotId){prepared.set(record.id,index);return index;}await new Promise(r=>setTimeout(r,350));}throw Error('stale');}
async function select(i:number,play=false){clearTimeout(scrubTimer);clearTimeout(timer);if(!play)playing.value=false;const token=++epoch,record=chronological.value[i],valid=request.capture();if(!record)return;busy.value=true;error.value='';position.value=i;try{const index=await prepare(record,token);if(!alive||token!==epoch||!valid())return;emit('snapshot',index);for(let attempt=0;alive&&token===epoch&&(props.activeSnapshot!==index.snapshotId||(props.renderedSnapshot!==undefined&&props.renderedSnapshot!==index.snapshotId));attempt++){if(attempt>200)throw Error('snapshot_timeout');await new Promise(r=>setTimeout(r,50));}if(!alive||token!==epoch)return;const nextDiff=diffs.get(record.id)??await request.invoke<KnowledgeDiff>('knowledgeDiff',{projectId:props.projectId,head:head.value,revision:record.id});if(!alive||token!==epoch||!valid())return;diff.value=nextDiff;diffs.delete(record.id);diffs.set(record.id,nextDiff);while(diffs.size>3)diffs.delete(diffs.keys().next().value!);const next=chronological.value[i+1];if(next)void prepare(next,token).then(index=>{if(alive&&token===epoch&&valid())emit('prefetch',index);}).catch(()=>{});if(playing.value&&next)timer=setTimeout(()=>void select(i+1,true),Number(speed.value));else playing.value=false;}catch{if(alive&&token===epoch){playing.value=false;error.value='历史快照未能准备完成，已停止播放。';}}finally{if(alive&&token===epoch)busy.value=false;}}
function scrub(i:number){stop();position.value=i;busy.value=true;scrubTimer=setTimeout(()=>void select(i),100);}
function stop(){playing.value=false;clearTimeout(scrubTimer);clearTimeout(timer);epoch++;busy.value=false;}
function latest(){stop();position.value=-1;diff.value=undefined;emit('latest');}
async function play(){if(playing.value){stop();return;}while(cursor.value&&alive){await load();if(error.value)return;}playing.value=true;void select(position.value<0||position.value>=chronological.value.length-1?0:position.value+1,true);}
function openChange(c:KnowledgeChange){const id=c.kind==='deleted'?diff.value?.beforeSnapshotId:diff.value?.afterSnapshotId;if(id)emit('open',id,c.path);}
function locateDate(value=date.value){const i=chronological.value.findIndex(r=>r.at.slice(0,10)>=value);if(i>=0)void select(i);}
watch([()=>props.activeCommit,chronological],()=>{if(!busy.value&&!playing.value&&props.activeCommit)position.value=chronological.value.findIndex(r=>r.id===props.activeCommit);});
function visibility(){if(document.hidden)stop();}
onMounted(()=>{void load();document.addEventListener('visibilitychange',visibility);});onBeforeUnmount(()=>{alive=false;stop();document.removeEventListener('visibilitychange',visibility);});
</script>
<template><section class="kb-timeline" aria-label="知识更新与时间轴"><div class="kb-time-controls"><Button variant="outline" @click="latest">返回最新</Button><Button variant="outline" :disabled="!records.length" @click="play">{{playing?'暂停':'播放主线历史'}}</Button><Button variant="outline" :disabled="position<=0" @click="select(position-1)">上一步</Button><Button variant="outline" :disabled="position>=records.length-1" @click="select(position+1)">下一步</Button><NativeSelect v-model="speed" aria-label="回放速度"><option value="2000">0.5×</option><option value="1000">1×</option><option value="500">2×</option></NativeSelect><Input v-model="date" type="date" aria-label="定位历史日期" @change="locateDate(($event.target as HTMLInputElement).value)"/></div><input v-if="records.length" type="range" aria-label="知识历史时间轴" :min="0" :max="records.length-1" :value="Math.max(0,position)" @input="scrub(Number(($event.target as HTMLInputElement).value))"/><p role="status">{{busy?'正在准备历史快照…':position<0?(activeCommit?'历史版本 '+safe(activeCommit):'当前工作区（含未提交变化）'):safe(chronological[position]?.at)+' · '+safe(chronological[position]?.title)}} · 已加载 {{records.length}} 个状态</p><StatusNotice v-if="notice" tone="warning">{{notice}}</StatusNotice><StatusNotice v-if="error" tone="error">{{error}}<Button @click="error='';load()">重试</Button></StatusNotice><details :open="!!diff"><summary>知识更新列表</summary><div class="kb-time-controls"><Input v-model="filter" aria-label="筛选知识更新" placeholder="Feature、知识区或路径"/><NativeSelect v-model="kind" aria-label="变更类型"><option value="">全部变更</option><option value="added">新增</option><option value="modified">修改</option><option value="deleted">删除</option><option value="renamed">重命名</option></NativeSelect></div><p v-if="diff">关系新增 {{diff.relationsAdded?.length??0}} · 关系删除 {{diff.relationsRemoved?.length??0}}</p><div v-if="diff" class="kb-change-list"><div v-for="c in changes" :key="c.path"><span>{{({added:'新增',modified:'修改',deleted:'删除',renamed:'重命名'} as Record<string,string>)[c.kind]}}</span><Button variant="link" @click="openChange(c)">{{safe(c.entry.title)}} · {{safe(c.path)}}</Button><Button variant="ghost" @click="emit('compare',diff.beforeSnapshotId,diff.afterSnapshotId,c.path,c.previousPath)">对比</Button></div><p v-if="!changes.length">此状态无匹配的文档变化。</p></div><div class="kb-commits"><Button v-for="r in records" :key="r.id" variant="ghost" @click="select(chronological.findIndex(c=>c.id===r.id))">{{safe(r.at)}} · {{safe(r.title)}}</Button></div><Button v-if="cursor" variant="outline" @click="load">加载更早历史</Button></details></section></template>
<style scoped>.kb-timeline{padding:16px;margin-top:16px;border:1px solid var(--ocp-border);border-radius:10px;font-size:12px}.kb-time-controls{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px;align-items:center}.kb-time-controls input[type=date]{width:160px}.kb-timeline input[type=range]{width:100%}.kb-timeline input:not([type=range]){background:var(--ocp-background);color:inherit;border:1px solid var(--ocp-border);border-radius:6px;padding:7px}.kb-commits{display:grid;max-height:240px;overflow:auto}.kb-commits button{justify-content:flex-start;height:auto;text-align:left;white-space:normal}.kb-change-list{max-height:300px;overflow:auto}.kb-change-list>div{display:flex;align-items:center;gap:8px}.kb-change-list button{white-space:normal;height:auto}summary{cursor:pointer}</style>
